from io import BytesIO
from unittest.mock import patch

import requests

from gtts import gTTS, gTTSError


def custom_error():
    error = gTTSError("Custom error message")
    try:
        raise error
    except gTTSError as caught:
        assert caught is error
        assert str(caught) == "Custom error message"
        assert caught.args == ("Custom error message",)
        print(f"Caught custom gTTSError: {caught}")


def request_error():
    tts = gTTS("Hello", lang_check=False)
    with patch("gtts.tts.requests.Session.send", side_effect=requests.exceptions.ConnectionError("offline")):
        try:
            tts.write_to_fp(BytesIO())
        except gTTSError as caught:
            assert caught.tts is tts
            assert str(caught) == "Failed to connect. Probable cause: Unknown"
            print(f"Caught request gTTSError: {caught}")


def invalid_language():
    try:
        gTTS("Hello", lang="xyz")
    except ValueError as caught:
        assert str(caught) == "Language not supported: xyz"
        print(f"Caught expected validation ValueError: {caught}")
    else:
        raise AssertionError("Invalid language was not rejected")


failures = 0
for check in (custom_error, request_error, invalid_language):
    try:
        check()
    except Exception as error:
        failures += 1
        print(f"FAIL {check.__name__}: {type(error).__name__}: {error}")

raise SystemExit(bool(failures))
PY
PYTHONPATH=/testbed python /tmp/gtts_error_repro.py
python -m pytest -q gtts/tests/test_tts.py -k 'test_msg or test_infer_msg'
